// TypeScript Version: 4.1

/**
* Evaluates the natural logarithm of the probability density function (logPDF)
* for a Bradford distribution.
*
* @param x - input value
* @returns evaluated logPDF
*/
type Unary = ( x: number ) => number;


/**
* Interface for the logarithm of the probability density function (logPDF) of a Bradford distribution.
*/
interface LogPDF {
	/**
	* Evaluates the natural logarithm of the probability density function (logPDF) for a Bradford distribution with shape parameter `c` at a value `x`.
	*
	* ## Notes
	*
	* -   If provided `c <= 0`, the function returns `NaN`.
	* -   If `x` is outside the interval [0,1], the function returns `-Infinity`.
	*
	* @param x - input value
	* @param c - shape parameter
	* @returns evaluated logPDF
	*
	* @example
	* var v = logpdf( 0.1, 0.1 );
	* // returns ~0.038
	*
	* @example
	* var v = logpdf( 0.5, 5.0 );
	* // returns ~-0.227
	*
	* @example
	* var v = logpdf( 1.0, 10.0 );
	* // returns ~-0.970
	*
	* @example
	* var y = logpdf( 2.0, 0.5 );
	* // returns -Infinity
	*
	* @example
	* var y = logpdf( -1.0, 0.5 );
	* // returns -Infinity
	*
	* @example
	* var y = logpdf( 0.5, 0.0 );
	* // returns NaN
	*
	* @example
	* var y = logpdf( 0.5, -5.0 );
	* // returns NaN
	*
	* @example
	* var y = logpdf( NaN, 1.0 );
	* // returns NaN
	*
	* @example
	* var y = logpdf( 1.0, NaN );
	* // returns NaN
	*/
	( x: number, c: number ): number;

	/**
	* Returns a function for evaluating the natural logarithm of the probability density function (logPDF) for a Bradford distribution with shape parameter `c`.
	*
	* @param c - shape parameter
	* @returns logPDF
	*
	* @example
	* var mylogpdf = logpdf.factory( 5.0 );
	* var y = mylogpdf( 0.5 );
	* // returns ~-0.227
	*
	* y = mylogpdf( 1.0 );
	* // returns ~-0.766
	*/
	factory( c: number ): Unary;
}

/**
* Bradford distribution logarithm of the probability density function (logPDF).
*
* @param x - input value
* @param c - shape parameter
* @returns evaluated logPDF
*
* @example
* var y = logpdf( 0.5, 5.0 );
* // returns ~-0.227
*
* var mylogpdf = logpdf.factory( 5.0 );
* y = mylogpdf( 0.5 );
* // returns ~-0.227
*
* y = mylogpdf( 1.0 );
* // returns ~-0.766
*/
declare var logpdf: LogPDF;


// EXPORTS //

export = logpdf;
